module histories::callable;struct Fn<T>{run:fn(T)->T;}
fn invoke<T>(f:fn(T)->T,value:T)->T{return f(value);}
server fn main()->i64 !{task,fs}{let offset:i64=42-1;let add:Fn<i64>=Fn(fn(x:i64)->i64{return x+offset;});assert(invoke(add.run,1)==42);
let text:str="Привет 🧠";assert(len(text)==8);assert(1.5+2.5==4.0);let f:file=unwrap(file_open_read("input"));assert(unwrap(file_size(f))==6);assert(file_close(f));return 42;}

client fn client_value()->i64{return 42;}
test fn pure_answer()->unit{assert(42>41);}

